import{_ as e,o as d,c as a,a0 as r}from"./chunks/framework.l1I-fhud.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function c(s,t,i,n,l,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><blockquote><p>Seeded from a copy of <code>cuora</code> (its ports-and-adapters anatomy and the <code>-cf</code> Worker pattern).</p></blockquote><p>tamias is <strong>ports-and-adapters</strong>. The engine owns the generic half of distribution; every content <em>meaning</em> is an adapter.</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Role</th><th>Impls</th></tr></thead><tbody><tr><td><code>ref</code></td><td>claims + parses a ref into an opaque spec</td><td>one per kind (in the <code>source-*</code> crates)</td></tr><tr><td><code>source</code></td><td><code>plan(spec)</code> → <code>fetch(plan, into)</code></td><td><code>-fs</code>, <code>-git</code>, <code>-http</code>, <code>-cf</code></td></tr><tr><td><code>store</code></td><td>put/get/verify an installed package</td><td><code>-local</code>, <code>-cf</code></td></tr><tr><td><code>cache</code></td><td>content-addressed fetch cache</td><td><code>-local</code>, <code>-cf</code></td></tr><tr><td><code>registry</code></td><td>index + publish</td><td><code>-local</code>, <code>-cf</code> (Worker + R2 + D1/KV)</td></tr><tr><td><code>deploy</code></td><td>service unit + teardown</td><td><code>-local</code> (systemd)</td></tr><tr><td><code>driver</code></td><td>how a content <em>type</em> installs/deploys</td><td><code>tamias-driver-&lt;type&gt;</code> (subprocess, argv)</td></tr></tbody></table><h2 id="crate-map" tabindex="-1">Crate map <a class="header-anchor" href="#crate-map" aria-label="Permalink to &quot;Crate map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>tamias-core</code></td><td>domain</td><td>Pure domain — package identity (@scope/name@semver), refs, manifests, records, digests (no I/O)</td></tr><tr><td><code>tamias-cache</code></td><td>port</td><td>cache port — read-through fetched content</td></tr><tr><td><code>tamias-config</code></td><td>port</td><td>Config port — where tamias.toml-shaped config comes from</td></tr><tr><td><code>tamias-deploy</code></td><td>port</td><td>deploy port — provision a remote registry (Worker + R2 + D1/KV)</td></tr><tr><td><code>tamias-registry</code></td><td>port</td><td>registry port — index + publish</td></tr><tr><td><code>tamias-source</code></td><td>port</td><td>source port — turn a ref into bytes</td></tr><tr><td><code>tamias-store</code></td><td>port</td><td>store port — content-addressed blobs</td></tr><tr><td><code>tamias-cache-cf</code></td><td>adapter</td><td>Cloudflare adapter (P6)</td></tr><tr><td><code>tamias-cache-local</code></td><td>adapter</td><td>local cache impl — content-addressed fetch cache</td></tr><tr><td><code>tamias-config-toml</code></td><td>adapter</td><td>TOML config impl</td></tr><tr><td><code>tamias-config-yml</code></td><td>adapter</td><td>YAML config impl (the standard) — tamias.yml / tamias.yaml</td></tr><tr><td><code>tamias-deploy-cf</code></td><td>adapter</td><td>Cloudflare deploy impl — the registry Worker + wrangler config</td></tr><tr><td><code>tamias-deploy-launchd</code></td><td>adapter</td><td>macos deploy impl — manage a per-user launchd agent (LaunchAgents plist + launchctl)</td></tr><tr><td><code>tamias-deploy-systemd</code></td><td>adapter</td><td>systemd deploy impl — manage a per-user service unit (Linux)</td></tr><tr><td><code>tamias-deploy-windows</code></td><td>adapter</td><td>windows deploy impl — manage a per-user scheduled task (Task Scheduler via schtasks.exe)</td></tr><tr><td><code>tamias-driver</code></td><td>adapter</td><td>content driver host — discovery + dispatch of tamias-driver-&lt;type&gt; (no product knowledge)</td></tr><tr><td><code>tamias-driver-tamias</code></td><td>adapter</td><td>tamias-driver-tamias — pavo view driver over the tamias install store, fetch cache, registry index, and driver dir (read-only)</td></tr><tr><td><code>tamias-install</code></td><td>adapter</td><td>The shared install pipeline — ref → fetch/cache → manifest → driver dispatch → store commit</td></tr><tr><td><code>tamias-provider</code></td><td>adapter</td><td>provider lifecycle — installed <code>provider:</code> blocks → units, deploy/uninstall, run exec specs, journal argv</td></tr><tr><td><code>tamias-publish</code></td><td>adapter</td><td>author side — pack + push</td></tr><tr><td><code>tamias-registry-cf</code></td><td>adapter</td><td>Cloudflare registry impl — a Worker + R2 over HTTP</td></tr><tr><td><code>tamias-registry-local</code></td><td>adapter</td><td>dir registry impl — a folder index, servable over HTTP</td></tr><tr><td><code>tamias-registry-open</code></td><td>adapter</td><td>shared registry-source layer — name-or-ref resolution + named-source config CRUD</td></tr><tr><td><code>tamias-serve</code></td><td>adapter</td><td>ndjson JSON-RPC over stdio — the embedding surface</td></tr><tr><td><code>tamias-shell</code></td><td>adapter</td><td>Run a command in a working directory via bash -c — the generic shell-out helper</td></tr><tr><td><code>tamias-sign</code></td><td>adapter</td><td>Package signing — ssh-keygen -Y sign/verify (namespace tamias-package) over the provenance anchors</td></tr><tr><td><code>tamias-source-cf</code></td><td>adapter</td><td>Cloudflare registry source impl — the <code>cf:</code> ref arm</td></tr><tr><td><code>tamias-source-fs</code></td><td>adapter</td><td>fs source impl — local dirs and tarballs</td></tr><tr><td><code>tamias-source-git</code></td><td>adapter</td><td>git source impl — clone URL //subdir #rev</td></tr><tr><td><code>tamias-source-http</code></td><td>adapter</td><td>http source impl — .tgz GET + optional sha256 pin</td></tr><tr><td><code>tamias-source-registry</code></td><td>adapter</td><td>Registry-scoped install refs — the <code>&amp;lt;registry&amp;gt;:&amp;lt;name&amp;gt;[@&amp;lt;version&amp;gt;]</code> ref arm</td></tr><tr><td><code>tamias-store-cf</code></td><td>adapter</td><td>Cloudflare adapter (P6)</td></tr><tr><td><code>tamias-store-local</code></td><td>adapter</td><td>local store impl — a directory</td></tr><tr><td><code>tamias-telemetry</code></td><td>adapter</td><td>Opt-in OpenTelemetry layer over the tracing stack — OTLP export, W3C context propagation</td></tr><tr><td><code>tamias-testkit</code></td><td>adapter</td><td>Fixtures + adapter conformance for every port</td></tr><tr><td><code>tamias-tui</code></td><td>adapter</td><td>tamias — interactive package-manager TUI (ratatui); the <code>tamias ui</code> surface</td></tr><tr><td><code>tamias</code></td><td>binary</td><td>tamias — package &amp; content manager: fetch, store, cache, dispense</td></tr></tbody></table><h2 id="the-install-path" tabindex="-1">The install path <a class="header-anchor" href="#the-install-path" aria-label="Permalink to &quot;The install path&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ref ─► resolve ─► (cache hit?) ─► fetch ─► driver install ─► store</span></span></code></pre></div><p><code>include:</code> composes payloads: each entry resolves to a store payload or a recursively-installed ref, <code>overlay()</code> deep-merges bases (earlier includes win, local wins) and the <em>composed</em> tree is what drivers see, what gets digested, and what the store commits. <code>publish</code>/<code>bundle pack</code> flatten includes by default (<code>--keep-includes</code> ships the raw payload).</p><p><code>resolve</code> pins git refs to a commit sha up front, so the content- addressed cache can be hit <em>before</em> fetching. The fetch→unpack split is what makes repeat installs and air-gapped nodes free.</p><h2 id="stores" tabindex="-1">Stores <a class="header-anchor" href="#stores" aria-label="Permalink to &quot;Stores&quot;">​</a></h2><ul><li><strong>install store</strong> — <code>&lt;name&gt;@&lt;version&gt;/</code> with a record (source ref, resolved sha, payload digest, installed-at).</li><li><strong>fetch cache</strong> — content-addressed; <code>remove</code> never touches it.</li><li><strong>registry</strong> — where published content lives: a directory, or a Cloudflare Worker + R2 + D1/KV.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h2><p><code>verify</code> recomputes the payload digest against the record. Digest-pinned refs (<code>#sha256:…</code>, resolved shas) are the integrity contract — see <a href="/tamias/explanation/security.html">Security model</a> for the full trust story, including the <code>--allow-drivers</code> consent gate on payload-shipped drivers.</p><h2 id="the-embedding-surface" tabindex="-1">The embedding surface <a class="header-anchor" href="#the-embedding-surface" aria-label="Permalink to &quot;The embedding surface&quot;">​</a></h2><p><code>tamias serve</code> (the <code>tamias-serve</code> crate) runs the same install/list/info/verify/remove verbs plus the registry surface — <code>search</code>, <code>publish</code>, and <code>registry.list|get|add|remove</code> — as an <strong>ndjson JSON-RPC service over stdio</strong> for agents and daemons that want a persistent handle instead of one-shot CLI calls. Registry name-or-ref resolution and config writes go through <code>tamias-registry-open</code>, the same code the CLI verbs use. The protocol is specified in <a href="/tamias/reference/serve.html">serve reference</a>.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p><code>tamias-telemetry</code> is an opt-in OpenTelemetry layer over the tracing stack. Nothing exports unless you set an endpoint:</p><ul><li><code>TAMIAS_OTEL_ENDPOINT</code> — OTLP/HTTP base URL (the opt-in switch), or the standard <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> / <code>…_TRACES_ENDPOINT</code>.</li><li><code>TAMIAS_OTEL_SERVICE_NAME</code> / <code>OTEL_SERVICE_NAME</code> — <code>service.name</code>.</li><li>W3C <code>traceparent</code>/<code>tracestate</code> propagation is installed when export is on; <code>RUST_LOG</code>-style filtering still applies.</li></ul>',20)])])}const u=e(o,[["render",c]]);export{m as __pageData,u as default};
